/**
 * TableForm Component Tests
 *
 * Tests for table form validation, submission, and QR code generation.
 * This file tests both new table creation and table editing flows,
 * including validation, error handling, QR code generation, and deletion.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { render } from '@/__tests__/utils/test-utils'
import { createMockSupabaseClient } from '@/__tests__/mocks/supabase'
import TablesPage from '../page'
import type { RestaurantTable, TableStatus } from '@/types/database'

// Mock the Supabase client
vi.mock('@/lib/supabase/client', () => ({
  createClient: vi.fn(),
}))

// Mock the QR code generator
vi.mock('@/lib/qrcode/generator', () => ({
  generateQRCodeSVG: vi.fn(),
  generateQRCodePNG: vi.fn(),
  generateQRCodePDF: vi.fn(),
}))

// Import after mocking to get the mocked version
import { createClient } from '@/lib/supabase/client'
import { generateQRCodeSVG, generateQRCodePNG, generateQRCodePDF } from '@/lib/qrcode/generator'

/**
 * Create a mock restaurant table with optional overrides
 */
function createMockTable(overrides: Partial<RestaurantTable> = {}): RestaurantTable {
  return {
    id: 'table-' + Math.random().toString(36).substring(7),
    organization_id: 'org-test',
    table_number: 'Masa 1',
    qr_uuid: 'qr-' + Math.random().toString(36).substring(7),
    current_status: 'empty',
    last_ping_at: null,
    ...overrides,
  }
}

describe('TableForm', () => {
  const mockOrganizationId = 'test-org-id'
  const mockOrganizationSlug = 'test-restaurant'
  const mockOrganizationName = 'Test Restaurant'

  beforeEach(() => {
    vi.clearAllMocks()
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  describe('New Table Form', () => {
    describe('Form Rendering', () => {
      it('renders new table form when clicking add button', async () => {
        // Arrange
        const mockClient = createMockSupabaseClient()
        vi.mocked(createClient).mockReturnValue(mockClient as any)

        const fromMock = vi.fn(() => {
          return createMockQueryBuilder({ selectData: [] })
        })

        mockClient.from = fromMock as any

        function createMockQueryBuilder(config: any) {
          const queryBuilder = {
            select: vi.fn(() => queryBuilder),
            eq: vi.fn(() => queryBuilder),
            order: vi.fn(() => queryBuilder),
            then: vi.fn((callback) => {
              return Promise.resolve({
                data: config.selectData,
                error: null,
              }).then(callback)
            }),
          }
          return queryBuilder
        }

        const user = userEvent.setup()

        // Act
        render(<TablesPage />, {
          authContext: {
            organization: { id: mockOrganizationId, slug: mockOrganizationSlug } as any,
          },
        })

        await waitFor(() => {
          expect(screen.getByText('Masalar')).toBeInTheDocument()
        })

        const addButton = screen.getByText('Yeni Masa')
        await user.click(addButton)

        // Assert
        await waitFor(() => {
          expect(screen.getByText('Yeni Masa')).toBeInTheDocument()
        })

        expect(screen.getByLabelText('Masa Numarasi / Adi')).toBeInTheDocument()
        expect(screen.getByText('Olustur')).toBeInTheDocument()
        expect(screen.getByText('Iptal')).toBeInTheDocument()
      })

      it('displays helper text about QR code generation', async () => {
        // Arrange
        const mockClient = createMockSupabaseClient()
        vi.mocked(createClient).mockReturnValue(mockClient as any)

        const fromMock = vi.fn(() => {
          return createMockQueryBuilder({ selectData: [] })
        })

        mockClient.from = fromMock as any

        function createMockQueryBuilder(config: any) {
          const queryBuilder = {
            select: vi.fn(() => queryBuilder),
            eq: vi.fn(() => queryBuilder),
            order: vi.fn(() => queryBuilder),
            then: vi.fn((callback) => {
              return Promise.resolve({
                data: config.selectData,
                error: null,
              }).then(callback)
            }),
          }
          return queryBuilder
        }

        const user = userEvent.setup()

        // Act
        render(<TablesPage />, {
          authContext: {
            organization: { id: mockOrganizationId, slug: mockOrganizationSlug } as any,
          },
        })

        await waitFor(() => {
          expect(screen.getByText('Masalar')).toBeInTheDocument()
        })

        const addButton = screen.getByText('Yeni Masa')
        await user.click(addButton)

        // Assert
        await waitFor(() => {
          expect(
            screen.getByText(/Masa olusturulunca otomatik olarak benzersiz bir QR kodu uretilecektir/)
          ).toBeInTheDocument()
        })
      })
    })

    describe('Form Submission', () => {
      it('successfully creates a new table', async () => {
        // Arrange
        const mockClient = createMockSupabaseClient()
        vi.mocked(createClient).mockReturnValue(mockClient as any)

        const newTableId = 'new-table-123'

        const fromMock = vi.fn((table: string) => {
          if (table === 'restaurant_tables') {
            return createTablesQueryBuilder()
          }
          return createMockQueryBuilder({ selectData: [] })
        })

        mockClient.from = fromMock as any

        function createTablesQueryBuilder() {
          const queryBuilder = {
            select: vi.fn(() => queryBuilder),
            eq: vi.fn(() => queryBuilder),
            order: vi.fn(() => queryBuilder),
            insert: vi.fn(() => {
              return Promise.resolve({
                data: { id: newTableId },
                error: null,
              })
            }),
            then: vi.fn((callback) => {
              return Promise.resolve({
                data: [],
                error: null,
              }).then(callback)
            }),
          }
          return queryBuilder
