        const user = userEvent.setup()

        // Act
        render(<TablesPage />, {
          authContext: {
            organization: { id: mockOrganizationId, slug: mockOrganizationSlug } as any,
          },
        })

        await waitFor(() => {
          expect(screen.getByText('Masalar')).toBeInTheDocument()
        })

        const addButton = screen.getByText('Yeni Masa')
        await user.click(addButton)

        await waitFor(() => {
          expect(screen.getByLabelText('Masa Numarasi / Adi')).toBeInTheDocument()
        })

        const tableNumberInput = screen.getByLabelText('Masa Numarasi / Adi')
        await user.type(tableNumberInput, 'Masa 5')

        const submitButton = screen.getByText('Olustur')
        await user.click(submitButton)

        // Assert
        await waitFor(() => {
          expect(capturedTableData).toBeTruthy()
        })

        expect(capturedTableData.current_status).toBe('empty')
      })

      it('handles database error during table creation', async () => {
        // Arrange
        const mockClient = createMockSupabaseClient()
        vi.mocked(createClient).mockReturnValue(mockClient as any)

        const fromMock = vi.fn((table: string) => {
          if (table === 'restaurant_tables') {
            return createTablesQueryBuilder()
          }
          return createMockQueryBuilder({ selectData: [] })
        })

        mockClient.from = fromMock as any

        function createTablesQueryBuilder() {
          const queryBuilder = {
            select: vi.fn(() => queryBuilder),
            eq: vi.fn(() => queryBuilder),
            order: vi.fn(() => queryBuilder),
            insert: vi.fn(() => {
              return Promise.resolve({
                data: null,
                error: { message: 'Database error' },
              })
            }),
            then: vi.fn((callback) => {
              return Promise.resolve({
                data: [],
                error: null,
              }).then(callback)
            }),
          }
          return queryBuilder
        }

        function createMockQueryBuilder(config: any) {
          const queryBuilder = {
            select: vi.fn(() => queryBuilder),
            eq: vi.fn(() => queryBuilder),
            order: vi.fn(() => queryBuilder),
            then: vi.fn((callback) => {
              return Promise.resolve({
                data: config.selectData,
                error: null,
              }).then(callback)
            }),
          }
          return queryBuilder
        }

        const user = userEvent.setup()

        // Act
        render(<TablesPage />, {
          authContext: {
            organization: { id: mockOrganizationId, slug: mockOrganizationSlug } as any,
          },
        })

        await waitFor(() => {
          expect(screen.getByText('Masalar')).toBeInTheDocument()
        })

        const addButton = screen.getByText('Yeni Masa')
        await user.click(addButton)

        await waitFor(() => {
          expect(screen.getByLabelText('Masa Numarasi / Adi')).toBeInTheDocument()
        })

        const tableNumberInput = screen.getByLabelText('Masa Numarasi / Adi')
        await user.type(tableNumberInput, 'Masa 5')

        const submitButton = screen.getByText('Olustur')
        await user.click(submitButton)

        // Assert
        await waitFor(() => {
          expect(screen.getByText('Masa kaydedilirken bir hata olustu.')).toBeInTheDocument()
        })
      })
    })

    describe('Form Interactions', () => {
      it('allows canceling form', async () => {
        // Arrange
        const mockClient = createMockSupabaseClient()
        vi.mocked(createClient).mockReturnValue(mockClient as any)

        const fromMock = vi.fn(() => {
          return createMockQueryBuilder({ selectData: [] })
        })

        mockClient.from = fromMock as any

        function createMockQueryBuilder(config: any) {
          const queryBuilder = {
            select: vi.fn(() => queryBuilder),
            eq: vi.fn(() => queryBuilder),
            order: vi.fn(() => queryBuilder),
            then: vi.fn((callback) => {
              return Promise.resolve({
                data: config.selectData,
                error: null,
              }).then(callback)
            }),
          }
          return queryBuilder
        }

        const user = userEvent.setup()

        // Act
        render(<TablesPage />, {
          authContext: {
            organization: { id: mockOrganizationId, slug: mockOrganizationSlug } as any,
          },
        })

        await waitFor(() => {
          expect(screen.getByText('Masalar')).toBeInTheDocument()
        })

        const addButton = screen.getByText('Yeni Masa')
        await user.click(addButton)

        await waitFor(() => {
          expect(screen.getByText('Yeni Masa')).toBeInTheDocument()
        })

        const cancelButtons = screen.getAllByText('Iptal')
        const modalCancelButton = cancelButtons[cancelButtons.length - 1]
        await user.click(modalCancelButton)

        // Assert - modal should be closed
        await waitFor(() => {
          expect(screen.queryByLabelText('Masa Numarasi / Adi')).not.toBeInTheDocument()
        })
      })
    })
  })

  describe('Edit Table Form', () => {
    describe('Form Loading', () => {
      it('loads existing table data into form', async () => {
        // Arrange
        const mockTables = [
          createMockTable({
            id: 'table-1',
            table_number: 'Masa 3',
            qr_uuid: 'qr-uuid-1',
            current_status: 'empty',
            organization_id: mockOrganizationId,
          }),
        ]

        const mockClient = createMockSupabaseClient()
        vi.mocked(createClient).mockReturnValue(mockClient as any)

        const fromMock = vi.fn((table: string) => {
          if (table === 'restaurant_tables') {
            return createMockQueryBuilder({ selectData: mockTables })
          }
          return createMockQueryBuilder({ selectData: [] })
        })

        mockClient.from = fromMock as any

        function createMockQueryBuilder(config: any) {
          const queryBuilder = {
            select: vi.fn(() => queryBuilder),
            eq: vi.fn(() => queryBuilder),
            order: vi.fn(() => queryBuilder),
            then: vi.fn((callback) => {
              return Promise.resolve({
                data: config.selectData,
                error: null,
              }).then(callback)
            }),
          }
          return queryBuilder
