        const user = userEvent.setup()

        // Act
        render(<TablesPage />, {
          authContext: {
            organization: { id: mockOrganizationId, slug: mockOrganizationSlug } as any,
          },
        })

        await waitFor(() => {
          expect(screen.getByText('Masa 3')).toBeInTheDocument()
        })

        // Click edit button
        const editButton = screen.getByRole('button', { name: /Duzenle/i })
        await user.click(editButton)

        // Assert
        await waitFor(() => {
          expect(screen.getByText('Masa Duzenle')).toBeInTheDocument()
        })

        const tableNumberInput = screen.getByLabelText('Masa Numarasi / Adi') as HTMLInputElement
        expect(tableNumberInput.value).toBe('Masa 3')
      })
    })

    describe('Form Update', () => {
      it('successfully updates table information', async () => {
        // Arrange
        const mockTables = [
          createMockTable({
            id: 'table-1',
            table_number: 'Masa 3',
            qr_uuid: 'qr-uuid-1',
            current_status: 'empty',
            organization_id: mockOrganizationId,
          }),
        ]

        const mockClient = createMockSupabaseClient()
        vi.mocked(createClient).mockReturnValue(mockClient as any)

        const fromMock = vi.fn((table: string) => {
          if (table === 'restaurant_tables') {
            return createTablesQueryBuilder()
          }
          return createMockQueryBuilder({ selectData: [] })
        })

        mockClient.from = fromMock as any

        function createTablesQueryBuilder() {
          const queryBuilder = {
            select: vi.fn(() => queryBuilder),
            eq: vi.fn(() => queryBuilder),
            order: vi.fn(() => queryBuilder),
            update: vi.fn(() => updateQueryBuilder),
            then: vi.fn((callback) => {
              return Promise.resolve({
                data: mockTables,
                error: null,
              }).then(callback)
            }),
          }

          const updateQueryBuilder = {
            eq: vi.fn(() => updateQueryBuilder),
            then: vi.fn((callback) => {
              return Promise.resolve({
                data: null,
                error: null,
              }).then(callback)
            }),
          }

          return queryBuilder
        }

        function createMockQueryBuilder(config: any) {
          const queryBuilder = {
            select: vi.fn(() => queryBuilder),
            eq: vi.fn(() => queryBuilder),
            order: vi.fn(() => queryBuilder),
            then: vi.fn((callback) => {
              return Promise.resolve({
                data: config.selectData,
