        await user.click(editButton)

        await waitFor(() => {
          expect(screen.getByText('Masa Duzenle')).toBeInTheDocument()
        })

        const tableNumberInput = screen.getByLabelText('Masa Numarasi / Adi')
        await user.clear(tableNumberInput)
        await user.type(tableNumberInput, 'VIP Masa')

        const submitButton = screen.getByText('Guncelle')
        await user.click(submitButton)

        // Assert - modal should close
        await waitFor(() => {
          expect(screen.queryByText('Masa Duzenle')).not.toBeInTheDocument()
        })
      })
    })
