  describe('QR Code Generation', () => {
    describe('QR Code Modal', () => {
      it('displays download buttons for all formats', async () => {
        // Arrange
        const mockTables = [
          createMockTable({
            id: 'table-1',
            table_number: 'Masa 1',
            qr_uuid: 'qr-uuid-1',
            organization_id: mockOrganizationId,
          }),
