          expect(screen.getByText('SVG')).toBeInTheDocument()
        })

        expect(screen.getByText('PNG')).toBeInTheDocument()
        expect(screen.getByText('PDF (A5)')).toBeInTheDocument()
      })

      it('generates SVG QR code when clicking SVG button', async () => {
        // Arrange
        const mockTables = [
          createMockTable({
            id: 'table-1',
            table_number: 'Masa 1',
            qr_uuid: 'qr-uuid-1',
            organization_id: mockOrganizationId,
          }),
