        await user.click(qrButton)

        await waitFor(() => {
          expect(screen.getByText('SVG')).toBeInTheDocument()
        })

        // Click SVG download button
        const svgButton = screen.getByText('SVG')
        await user.click(svgButton)

        // Assert
        await waitFor(() => {
          expect(generateQRCodeSVG).toHaveBeenCalledWith(mockOrganizationSlug, 'qr-uuid-1')
        })
